export function RedeScreen({ ctrl }) {
  const {
    fundo, reputacao, parecerAi, foiAvaliado, foiNegado,
    cashbackSaldo, TETO_CASHBACK, dadosOp, membro
  } = ctrl

  const territorios = [
    { nome: 'Zona Leste — SP', bairros: 'Itaquera · Guaianases · Cidade Tiradentes', cor: 'var(--color-gold)' },
    { nome: 'Zona Norte — SP', bairros: 'Brasilândia · Jaçanã · Tremembé', cor: 'var(--color-magenta)' },
    { nome: 'ABC Paulista', bairros: 'Mauá · Ribeirão Pires · Rio Grande da Serra', cor: 'var(--success)' },
  ]

  const cashbackPct = TETO_CASHBACK > 0 ? Math.round((cashbackSaldo / TETO_CASHBACK) * 100) : 0
  const membroRegiao = membro?.regiao || null

  return (
    <div className="screen active" id="screen-rede" style={{ paddingBottom: '24px' }}>
      {/* Header */}
      <div style={{ padding: '20px 20px 12px' }}>
        <span style={{ fontSize: '0.55rem', fontWeight: 800, padding: '3px 10px', background: 'rgba(224,36,124,0.1)', border: '1px solid rgba(224,36,124,0.3)', borderRadius: '20px', color: 'var(--color-magenta)', letterSpacing: '0.1em' }}>TERRITÓRIOS COMUNITÁRIOS</span>
        <h2 style={{ fontFamily: 'var(--font-heading)', fontSize: '1.6rem', fontWeight: 900, letterSpacing: '-0.03em', lineHeight: 1.1, marginTop: '10px' }}>
          Seu dinheiro fica<br />
          <em style={{ fontFamily: 'var(--font-italic)', color: 'var(--color-gold)', fontStyle: 'italic' }}>na sua rota.</em>
        </h2>
        <p style={{ fontSize: '0.72rem', color: 'var(--text-secondary)', lineHeight: 1.4, marginTop: '6px' }}>
          Qualquer comércio dentro das áreas mapeadas devolve R$ 2,00 por compra para você acumular.
        </p>
      </div>

      <div style={{ padding: '0 20px', display: 'flex', flexDirection: 'column', gap: '14px' }}>

        {/* Como funciona */}
        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '16px' }}>
          <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '10px' }}>COMO FUNCIONA</p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {[
              { icon: 'fa-map-location-dot', cor: 'var(--color-gold)', texto: 'Entre em qualquer território comunitário mapeado pela Abias.' },
              { icon: 'fa-store', cor: 'var(--color-magenta)', texto: 'Compre em qualquer comércio local dentro da área — padaria, oficina, mercadinho.' },
              { icon: 'fa-coins', cor: 'var(--success)', texto: 'R$ 2,00 são acumulados automaticamente no seu saldo cashback.' },
            ].map(({ icon, cor, texto }) => (
              <div key={icon} style={{ display: 'flex', alignItems: 'flex-start', gap: '10px' }}>
                <div style={{ width: '30px', height: '30px', borderRadius: '8px', background: 'rgba(255,255,255,0.04)', border: '1px solid var(--border-color)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                  <i className={`fa-solid ${icon}`} style={{ fontSize: '0.75rem', color: cor }}></i>
                </div>
                <p style={{ fontSize: '0.68rem', color: 'var(--text-secondary)', lineHeight: 1.45, paddingTop: '4px' }}>{texto}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Saldo cashback do membro */}
        {reputacao > 0 ? (
          <div style={{ background: 'linear-gradient(135deg, rgba(22,61,47,0.4) 0%, rgba(11,11,11,0.8) 100%)', border: '1px solid rgba(74,222,128,0.15)', borderRadius: '12px', padding: '16px' }}>
            <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '6px' }}>SEU SALDO CASHBACK</p>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1.8rem', fontWeight: 700, color: 'var(--success)', lineHeight: 1 }}>
              R$ {cashbackSaldo.toFixed(2)}
            </div>
            <p style={{ fontSize: '0.62rem', color: 'var(--text-secondary)', marginTop: '4px' }}>
              Acumulado em compras dentro dos territórios
            </p>
            <div style={{ marginTop: '10px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px' }}>
                <span style={{ fontSize: '0.58rem', color: 'var(--text-secondary)' }}>Progresso até o teto</span>
                <span style={{ fontSize: '0.58rem', fontFamily: 'var(--font-mono)', color: 'var(--success)' }}>
                  {cashbackPct}% de R$ {TETO_CASHBACK}
                </span>
              </div>
              <div style={{ height: '4px', background: 'rgba(255,255,255,0.06)', borderRadius: '2px' }}>
                <div style={{ width: `${Math.min(100, cashbackPct)}%`, height: '100%', background: 'linear-gradient(90deg, #22c55e, #4ade80)', borderRadius: '2px', transition: 'width 0.5s ease' }}></div>
              </div>
            </div>
            {dadosOp && (
              <p style={{ fontSize: '0.6rem', color: 'var(--text-secondary)', marginTop: '8px' }}>
                Região ativa: <strong style={{ color: 'var(--text-primary)' }}>{membroRegiao || 'não informada'}</strong>
              </p>
            )}
          </div>
        ) : (
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '16px' }}>
            <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '8px' }}>SEU SALDO CASHBACK</p>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <i className="fa-solid fa-clock" style={{ fontSize: '1.4rem', color: 'rgba(255,255,255,0.15)' }}></i>
              <div>
                <p style={{ fontSize: '0.78rem', fontWeight: 700, color: 'var(--text-primary)' }}>
                  {foiNegado ? 'Cashback indisponível' : 'Aguardando avaliação'}
                </p>
                <p style={{ fontSize: '0.62rem', color: 'var(--text-secondary)', marginTop: '2px' }}>
                  {foiNegado
                    ? 'Seu perfil não atingiu o score mínimo para acúmulo de cashback.'
                    : 'O cashback é liberado após a IA analisar seu perfil operacional.'}
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Territórios mapeados */}
        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', overflow: 'hidden' }}>
          <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border-color)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h5 style={{ fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.1em' }}>TERRITÓRIOS MAPEADOS</h5>
            <span style={{ fontSize: '0.55rem', fontFamily: 'var(--font-mono)', color: 'var(--text-secondary)' }}>PILOTO • 3 ÁREAS</span>
          </div>
          {territorios.map(({ nome, bairros, cor }) => (
            <div key={nome} style={{ padding: '12px 16px', borderBottom: '1px solid rgba(255,255,255,0.04)', display: 'flex', alignItems: 'center', gap: '10px' }}>
              <div style={{ width: '34px', height: '34px', borderRadius: '8px', background: 'rgba(255,255,255,0.03)', border: '1px solid var(--border-color)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <i className="fa-solid fa-map-pin" style={{ fontSize: '0.75rem', color: cor }}></i>
              </div>
              <div style={{ flex: 1 }}>
                <h6 style={{ fontSize: '0.75rem', fontWeight: 700 }}>{nome}</h6>
                <p style={{ fontSize: '0.6rem', color: 'var(--text-secondary)' }}>{bairros}</p>
              </div>
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.7rem', fontWeight: 800, color: 'var(--success)', flexShrink: 0 }}>+ R$ 2</span>
            </div>
          ))}
          <div style={{ padding: '12px 16px', background: 'rgba(201,154,61,0.04)' }}>
            <p style={{ fontSize: '0.6rem', color: 'var(--text-secondary)', lineHeight: 1.4 }}>
              <i className="fa-solid fa-circle-info" style={{ marginRight: '5px', color: 'var(--color-gold)' }}></i>
              Não há parceria comercial. Qualquer estabelecimento dentro da área participante conta — sem cadastro prévio.
            </p>
          </div>
        </div>

        {/* Parecer AI — só se aprovado */}
        {reputacao > 0 && parecerAi && (
          <div style={{ background: 'var(--bg-card)', border: '1px solid rgba(74,222,128,0.2)', borderRadius: '12px', padding: '16px' }}>
            <p style={{ fontSize: '0.55rem', color: 'var(--success)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '8px' }}>ANÁLISE DE CRÉDITO — IMPACTO NA REDE</p>
            <p style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
              {parecerAi.consideracaoEquidade || parecerAi.analise}
            </p>
          </div>
        )}

        {/* Quote */}
        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '20px' }}>
          <p style={{ fontFamily: 'var(--font-italic)', fontStyle: 'italic', fontSize: '0.88rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
            "Onde o dinheiro circula dentro da rota, a rota se fortalece."
          </p>
        </div>

        {/* Fundo Abias */}
        <div style={{ background: 'var(--bg-card)', border: '1px solid rgba(201,154,61,0.2)', borderRadius: '12px', padding: '16px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
            <div>
              <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '4px' }}>FUNDO ABIAS</p>
              <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1.5rem', fontWeight: 700, color: 'var(--color-gold)', lineHeight: 1 }}>
                R$ {fundo.toFixed(2)}
              </div>
            </div>
            <span style={{ fontSize: '0.55rem', fontWeight: 800, padding: '4px 8px', background: 'rgba(201,154,61,0.1)', border: '1px solid rgba(201,154,61,0.3)', borderRadius: '20px', color: 'var(--color-gold)' }}>PILOTO</span>
          </div>
          <div style={{ height: '4px', background: 'rgba(255,255,255,0.06)', borderRadius: '2px' }}>
            <div style={{ width: `${Math.min(100, (fundo / 8000) * 100)}%`, height: '100%', background: 'linear-gradient(90deg, #C99A3D, #F2C96E)', borderRadius: '2px', transition: 'width 0.5s ease' }}></div>
          </div>
          <p style={{ fontSize: '0.6rem', color: 'var(--text-secondary)', marginTop: '6px' }}>Meta de blindagem: R$ 8.000,00</p>
        </div>

      </div>
    </div>
  )
}
